    guide_text_811b147eb27130a7: "যেখানেই নথি তালিকাভুক্ত হয়",
    guide_text_ec1f7d4d6b61a9aa: "শহর যা কিনতে চায় সে বিষয়ে সাড়া দেওয়ার প্রকাশিত আমন্ত্রণ",
    guide_text_4d52521e4bdde1b7: "শহর কাকে কাজ দিতে চায় তার প্রকাশিত বিবৃতি",
    guide_text_59026f820d3f4c0a: "প্রদানের পর চুক্তি কার্যকর করার ধাপ, আলাদা নথি হিসেবে প্রকাশিত",
    guide_text_2176ef1b6b2c07fb: "নোটিশে চুক্তির জীবনচক্র",
    guide_text_0f56c2f94e285f99: "সংস্থার কাজের পদ্ধতির পরিবর্তন, গ্রহণের আগে প্রকাশ করতে হয়",
    guide_text_d9232514542a8a69: "আইনি দায়িত্ব",
    guide_text_9b73c85478d03ba8: "আইন অনুযায়ী সংস্থার দায়িত্ব—প্রতিবেদন, বিধি তৈরি বা কিছু আয়োজন করা—যার প্রমাণ তার প্রকাশনায় থাকে",
