    guide_text_9822a9ced8a4a0b5: "উত্তীর্ণদের ক্রমযুক্ত তালিকা, যেখান থেকে সংস্থা নিয়োগ দেয়",
    guide_text_eed88f3aa1edf2d6: "এর অর্থ",
