    guide_text_3103aec7649a7f3c: "বরোর মধ্যে নম্বরযুক্ত নিযুক্ত স্থানীয় বোর্ড",
    guide_text_c47d5976501ed936: "একাধিক বরোতে বোর্ড 7 আছে; শুধু নম্বর একটি বোর্ড বোঝায় না",
    guide_text_3a7d9400aa565aec: "কমিউনিটি বোর্ড যে এলাকা জুড়ে কাজ করে",
