    public_input_explainer_open: "জনমত কীভাবে কাজ করে",
    public_input_explainer_what_html: "<p>কোনো সরকারি কার্যক্রমে অংশ নেওয়া মানে দাপ্তরিক নথিতে কিছু রেখে যাওয়া: শুনানিতে বলা, বা প্রকাশিত সময়সীমার আগে লিখিত মতামত পাঠানো। সেই নথি এরপর কী করে তা কার্যক্রমভেদে আলাদা, আর এই সাইটের প্রতিটি তালিকাভুক্তি জানায় কোনটি তার ক্ষেত্রে প্রযোজ্য।</p>",
    public_input_explainer_destinations_heading: "আপনার বলা কথা শেষ পর্যন্ত কোথায় যায়",
    public_input_explainer_destinations_html: "<ul><li><b>জনসাধারণের মতামতের নথি</b> — মতামত গ্রহণের সময়ে জমা দেওয়া লিখিত মতামত সেই নথিতে যোগ হয় যা সংস্থাকে বিবেচনা করতে হয়।</li><li><b>শুনানির সাক্ষ্য</b> — শুনানিতে আপনি যা বলেন তা সেই শুনানির সাক্ষ্য-নথিতে যোগ হয়।</li><li><b>অনুলিপি</b> — কিছু কার্যক্রম অধিবেশনের হুবহু বিবরণ প্রকাশ করে।</li><li><b>কার্যবিবরণী</b> — অন্য সংস্থাগুলো তার বদলে যা ঘটেছে তার সারসংক্ষেপ প্রকাশ করে।</li><li><b>সিদ্ধান্তের দলিল</b> — একটি পৃথক নথি, সংস্থা সিদ্ধান্ত নথিভুক্ত করলে প্রকাশিত হয়।</li></ul><p>কিছু কার্যক্রম প্রাপ্ত মতামতের জবাবে একটি প্রতিবেদনও প্রকাশ করে। এটি এই গন্তব্যগুলোর একটি, আর প্রতিটি তালিকাভুক্তি জানায় তা প্রযোজ্য কি না।</p>",
    public_input_explainer_limits_heading: "অংশ নেওয়ার সীমা",
    public_input_explainer_limits_html: "<p>কর্মকর্তার জবাব আর নথিভুক্তি এক জিনিস নয়। মতামত জমা দেওয়া বা সাক্ষ্য দেওয়া আপনার কথা নথিতে তোলে, আর কোনো কর্মকর্তা আপনাকে ব্যক্তিগতভাবে জবাব দিতে বাধ্য নন। এই সাইট এমন কোনো জবাবের প্রতিশ্রুতি দেয় না।</p><p>মতামতের সংখ্যা কেবল সংখ্যাই থাকে। সংস্থা যে আইনের অধীনে চলে তার নিরিখে বক্তব্য বিচার করে, তাই এই সাইট কোনো মতামতের মোটকে সমর্থন বা বিরোধিতা হিসেবে দেখায় না এবং মতামতের পরিমাণকে ভোট হিসেবে গণ্য করে না।</p>",
    public_input_explainer_examples_heading: "বাস্তবে এটি কাজ করার তিনটি ধরন",
    public_input_explainer_example_hearing: "কোনো বিল নিয়ে সিটি কাউন্সিলের শুনানিতে বলুন, বা লিখিত সাক্ষ্য পাঠান।",
    public_input_explainer_example_hearing_surface: "নির্ধারিত শুনানি ও সভা দেখুন",
    public_input_explainer_example_rule: "প্রকাশিত সময়সীমার আগে কোনো সংস্থার প্রস্তাবিত বিধি নিয়ে মতামত দিন।",
    public_input_explainer_example_rule_surface: "খোলা বিধি-মতামতের সময়কাল দেখুন",
    public_input_explainer_example_contract: "মতামতের সময়সীমার মধ্যে প্রস্তাবিত চুক্তি প্রদান নিয়ে মতামত দিন।",
    public_input_explainer_example_contract_surface: "চুক্তির মতামতের সময়সীমা দেখুন",
    public_input_explainer_official_source: "দাপ্তরিক উৎস: {source}",
    public_input_explainer_method_summary: "এই ব্যাখ্যাটি কোথা থেকে এসেছে",
    public_input_explainer_method_html: "<p>উপরের প্রতিটি উদাহরণ সেই নগর পাতার সঙ্গে যুক্ত যা তা পরিচালনা করে, এবং এই সাইটের যে অংশ সেই ধরনের চলমান নথি তালিকাভুক্ত করে তার সঙ্গেও। এই ব্যাখ্যা বলছে ওই কার্যক্রমগুলো সাধারণভাবে কীভাবে চলে; কোনো একটির নির্দিষ্ট তারিখ, অবস্থা, উদ্দেশ্য ও অংশগ্রহণের পথ তার নিজের তালিকাভুক্তিতেই থাকে, তার নগর নথি উৎস-লিঙ্কের পাশে।</p>",
