    zap_explainer_html: "পুনঃজোনিং তথ্য NYC-এর Zoning Application Portal (ZAP) থেকে NYC Open Data-এর মাধ্যমে আসে, যা শহরটি প্রায় মাসিক হালনাগাদ করে। লাইভ ZAP সাইটের পরিবর্তন এখানে আসতে কয়েক সপ্তাহ সময় নিতে পারে। লট সীমারেখা ZAP Search-এ বর্ণিত একই ট্যাক্স-লট (BBL) → MapPLUTO যোগ ব্যবহার করে। লট মিল না হলে মানচিত্র আনুমানিক — ZoLa-তে নিশ্চিত করুন।",
