    about_pasttask_task_html: "<b>কাজ:</b> আপনি আসলে কী করার চেষ্টা করছিলেন?",
    about_pasttask_breakdown_html: "<b>কোথায় সমস্যা হয়েছিল:</b> কী হয়েছিল, বা কোথায় এটি আপনার প্রত্যাশা অনুযায়ী কাজ করা বন্ধ করে দিয়েছিল?",
    about_pasttask_workaround_html: "<b>আপনি পরিবর্তে কী করেছিলেন:</b> আপনি কি অন্য উপায় খুঁজে পেয়েছিলেন, ছেড়ে দিয়েছিলেন, নাকি অসম্পূর্ণ রেখে দিয়েছিলেন?",
    about_pasttask_note: "এগুলো শুধু ইঙ্গিত। নিচে নিজের ভাষায় আপনার উত্তর লিখুন — পূরণ করার জন্য আলাদা কোনো ক্ষেত্র নেই।",
    about_ph_message: "কী ঘটেছে, আপনি কী চাইতেন, বা অন্য কিছু — যত নির্দিষ্ট, তত ভালো।",
    about_label_email: "ইমেইল",
    about_label_email_opt: "— ঐচ্ছিক, শুধু যদি আপনি উত্তর চান",
    about_btn_send: "মতামত পাঠান →",
    about_note_feedback_html: "আপনি ইমেইল দিলে আমরা শুধু উত্তর দেওয়ার জন্য তা ব্যবহার করি। স্প্যাম ঠেকাতে প্রতিটি জমার সঙ্গে আপনার IP ঠিকানা ও ব্রাউজারের তথ্য অল্প সময় রাখা হয়।",
    about_err_short: "আরেকটু বিস্তারিত যোগ করুন — অন্তত একটি বাক্য।",
    about_err_long: "এটি একটু বেশি লম্বা — অনুগ্রহ করে ২,০০০ অক্ষরের নিচে রাখুন।",
