    about_foot_html: "CityScroll · নিউ ইয়র্ক সিটির সরকারি নথি, সংযুক্ত · <a href=\"/guide/\">গাইড</a> · <a href=\"stats.html\">পরিসংখ্যান</a> · <a href=\"mailto:feedback%40cityscroll.org\">মতামত</a> · <a href=\"index.html\">হোম</a>",
    session_signed_in: "{email} হিসাবে সাইন ইন করা হয়েছে — পিনগুলি এই ডিভাইসে আপনার সাথে থাকে।",
    session_manage_watches: "সতর্কতা পরিচালনা করুন",
    session_not_you: "আপনি নন?",
    session_dismiss: "বন্ধ",
    data_p_lede_html: "নগর নথির উপাত্তসেট, এক নজরে। আপনার ব্রাউজার <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> (নতুন ট্যাবে খোলে)</span></a> থেকে লাইভ মোট টেনে আনে। সার্ভারে কিছুই সংরক্ষিত হয় না। সংখ্যাগুলি <a href=\"api.html#upstream\">সততার নিয়ম</a> অনুসরণ করে। পরিসংখ্যান তাদের নিজস্ব বিভাগের মধ্যেই থাকে। সম্ভাব্য উপাত্ত-প্রবেশের ভুল বাদ দেওয়া হয়েছে — $১০ বিলিয়ন বা তার বেশি পরিমাণ। স্থানধারক শেষ তারিখ প্রকৃত হিসেবে গণনা করা হয় না।",
    data_h_sections_html: "নথি আসলে কী দেখায় <span class=\"note\">(সব সময়, বিভাগ অনুযায়ী)</span>",
    data_note_sections_body: "নগর নথির বেশিরভাগই সিভিল-সার্ভিস চাকরি সম্পর্কিত কাগজপত্র। যেসব নোটিশ জনসাধারণের কাছে গুরুত্বপূর্ণ তা এর একটি ছোট অংশ মাত্র। তাই এই সাইটের প্রতিটি সংখ্যা প্রতি বিভাগ অনুযায়ী দেখানো হয়।",
    data_h_volume_html: "কতগুলি প্রকাশিত হয়েছে <span class=\"note\">(গত ১২ মাস)</span>",
    data_h_procmix_html: "ক্রয় সংমিশ্রণ <span class=\"note\">(গত ১২ মাস, নোটিশের ধরন অনুযায়ী)</span>",
    data_h_agencies_html: "প্রদত্ত অর্থ অনুযায়ী শীর্ষ সংস্থা <span class=\"note\">(গত ১২ মাস, পরিষ্কার করা)</span>",
    data_note_agencies_html: "\"পরিষ্কার করা\" মানে আমরা $১০ বিলিয়নের বেশি পরিমাণ বাদ দিয়েছি। আমরা মনে করি এগুলি উপাত্ত-প্রবেশের ভুল। দেখুন <a href=\"api.html#upstream\">অন্তর্নিহিত উপাত্ত</a>।",
    data_h_vendors_html: "প্রদত্ত অর্থ অনুযায়ী শীর্ষ বিক্রেতা <span class=\"note\">(গত ১২ মাস, পরিষ্কার করা)</span>",
    data_note_vendors: "উৎসে বিক্রেতার নাম মানসম্মত নয়। ছোট বানান পার্থক্য এখানে পৃথক সারি হিসেবে দেখা যায়।",
    data_value_share: "{value} · মোটের {share}",
