    data_foot_html: "প্রতিটি সংখ্যা সরকারি উপাত্তসেট থেকে আপনার ব্রাউজারে লাইভ হিসাব করা হয়। নতুন উপাত্তের জন্য পৃষ্ঠাটি রিলোড করুন। পদ্ধতি: <a href=\"api.html#upstream\">সম্পর্কে → অন্তর্নিহিত উপাত্ত</a> · <a href=\"stats.html\">সাইট ব্যবহারের পরিসংখ্যান</a>",
