    stats_area_staten_island: "স্ট্যাটেন আইল্যান্ড",
    api_p_intro_html: "CityScroll-এর প্রতিটি দৃশ্যের একটি যন্ত্র-পাঠযোগ্য প্রতিরূপ আছে। কোনো কী নেই, কোনো অ্যাকাউন্ট নেই; এন্ডপয়েন্টগুলি হার-সীমিত ও ক্যাশড, এবং কোনোটিই কোনো পেইড পরিষেবা স্পর্শ করে না। বেস URL: <code>https://api.cityscroll.org</code>।",
    api_h_feeds: "ফিড — RSS / JSON / ক্যালেন্ডার হিসেবে যেকোনো অনুসন্ধান",
    api_p_feeds_html: "<code>GET /feed.xml</code> (Atom) · <code>GET /feed.json</code> (JSON Feed 1.1) · <code>GET /feed.ics</code> (সাবস্ক্রাইবযোগ্য ক্যালেন্ডার — তারিখযুক্ত প্রতিটি নোটিশের জন্য একটি অনুষ্ঠান)। ১৫ মিনিট এজ-ক্যাশড।",
    api_th_param: "প্যারামিটার",
