    api_row_q: "মূল শব্দ (৪টি পর্যন্ত)",
    api_row_agency: "নথিতে মুদ্রিত অনুযায়ী সংস্থার নাম",
    api_row_min: "সর্বনিম্ন প্রদান $ (অর্থ লেন্স → প্রদান ফিড)",
    api_row_kindname_html: "সত্তা লেন্স: <code>kind=vendor|agency</code>, <code>name=…</code> — বিক্রেতার নাম মানসম্মত মূল শব্দ দ্বারা মেলানো হয়, তাই প্রত্যয়/অক্ষর-ভিন্নতা অন্তর্ভুক্ত থাকে",
    api_h_property_locations: "সম্পত্তির অবস্থান",
    api_p_property_locations_html: "<code>GET /property-locations</code> সর্বশেষ সম্পত্তি নিষ্পত্তির বিজ্ঞপ্তিগুলো থেকে শনাক্ত করা সাইটের ঠিকানা, বরো, ট্যাক্স লট, BBL এবং পাওয়া গেলে মানচিত্রের জ্যামিতি ফেরত দেয়। দৈনিক ভিউটি এজে ৩০ মিনিট ক্যাশে থাকে। City Record Online-ই মূল উৎস।",
    api_h_agencies: "সংস্থার নামের মিলতালিকা",
    api_p_agencies_html: "<code>GET /agencies</code> সিটি রেকর্ড ওপেন ডেটায় যেভাবে প্রতিটি সংস্থার নাম লেখা আছে তা তালিকাভুক্ত করে এবং এই সাইটে ব্যবহৃত একটি নামের সঙ্গে যুক্ত করে। CSV পেতে <code>?format=csv</code> যোগ করুন। এন্ডপয়েন্টটির কোনো কী লাগে না, ক্রস-সাইট অনুরোধ গ্রহণ করে এবং এক দিনের জন্য ক্যাশে থাকে।",
    api_agencies_dictionary_html: "<tr><td><code>raw_string</code></td><td><code>agency_name</code>-এর হুবহু লেখা; উৎসের প্রতিটি আলাদা স্ট্রিংয়ের জন্য একটি সারি</td></tr><tr><td><code>canonical_id</code></td><td>মিলতালিকা থেকে দেওয়া স্থিতিশীল টেক্সট আইডি</td></tr><tr><td><code>canonical_name</code></td><td>এই সাইটে গোষ্ঠীটির জন্য ব্যবহৃত নাম</td></tr><tr><td><code>variants</code></td><td>একই আইডির সঙ্গে যুক্ত উৎসের সব বানান</td></tr>",
    api_p_agencies_limits: "মিল খোঁজার সময় অক্ষরের ধরন, যতিচিহ্ন, পরিচিত সংক্ষিপ্ত রূপ ও প্রশাসনিক পরিবার ব্যবহার করা হয়। মিলতালিকা হালনাগাদ না হওয়া পর্যন্ত নতুন বানান নিজস্ব আইডি পেতে পারে। মিলতালিকাটি রেকর্ড যুক্ত করতে সাহায্য করে; এটি সরকারি সংস্থা নিবন্ধন নয়।",
    api_h_batch: "ব্যাচ ক্রস-রেফারেন্স",
    api_p_batch_html: "<code>{\"names\": [\"…\", …]}</code>-সহ <code>POST /batch</code> (≤১০ নাম/অনুরোধ, ৩০ অনুরোধ/দিন/আইপি)। প্রতিটি নামের জন্য: <b>প্রদান</b> = সেই বিক্রেতার নাম উল্লেখকারী প্রদান/অভিপ্রায় নোটিশ (নাম-মূল মেলানো, সব বছর); <b>উল্লেখ</b> = গত দুই বছরের সংস্করণে সম্পূর্ণ-লেখা মিল; <b>সত্তা</b> = প্রদান থাকলে বিক্রেতা-প্রোফাইলের স্থায়ী লিংক।",
